91	+package hotel.documents;
92	+
93	+import hotel.reservations.Price;
94	+import hotel.reservations.Reservation;
95	+import hotel.rooms.Room;
96	+
97	+/**
98	+ * The document the guest gets. Every document follows the same sequence of lines; each layout writes its own
99	+ * lines (language, identification, extras at the end).
100	+ */
101	+public abstract class DocumentLayout {
102	+
103	+    public abstract String title();
104	+
105	+    protected abstract String header(Reservation reservation);
106	+
107	+    protected abstract String guestLines(Reservation reservation);
108	+
109	+    protected abstract String roomLine(Room room);
110	+
111	+    protected abstract String stayLine(Reservation reservation);
112	+
113	+    protected abstract String chargesLine(Price price);
114	+
115	+    protected abstract String discountLine(Price price);
116	+
117	+    protected abstract String totalLine(Price price);
118	+
119	+    /** Lines after the total; none by default. */
120	+    protected String closingLines(Price price) {
121	+        return null;
122	+    }
123	+
124	+    public final String render(Reservation reservation, Room room) {
125	+        Price price = reservation.price();
126	+        StringBuilder text = new StringBuilder();
127	+        text.append(header(reservation)).append('\n');
128	+        text.append(guestLines(reservation)).append('\n');
129	+        text.append(roomLine(room)).append('\n');
130	+        text.append(stayLine(reservation)).append('\n');
131	+        text.append(chargesLine(price)).append('\n');
132	+        if (price.discount().signum() > 0) {
133	+            text.append(discountLine(price)).append('\n');
134	+        }
135	+        text.append(totalLine(price)).append('\n');
136	+        String closing = closingLines(price);
137	+        if (closing != null) {
138	+            text.append(closing).append('\n');
139	+        }
140	+        return text.toString();
141	+    }
142	+}
