+package hotel.documents;
+
+import hotel.reservations.Identification;
+import hotel.reservations.Price;
+import hotel.reservations.Reservation;
+import hotel.rooms.Room;
+
+/** The booking receipt, in English, for the foreign guest. */
+public class BookingReceiptLayout extends DocumentLayout {
+
+    @Override
+    public String title() {
+        return "Booking receipt";
+    }
+
+    @Override
+    protected String header(Reservation reservation) {
+        return title() + " no. " + reservation.id();
+    }
+
+    @Override
+    protected String guestLines(Reservation reservation) {
+        Identification guest = reservation.guest().identification();
+        return "Guest: " + reservation.guest().name() + " (passport " + guest.passport() + ", " + guest.country() + ")";
+    }
+
+    @Override
+    protected String roomLine(Room room) {
+        return "Room: " + room.number() + " (" + room.type() + ")";
+    }
+
+    @Override
+    protected String stayLine(Reservation reservation) {
+        int nights = reservation.price().nights();
+        return "Check-in: " + TextFormat.englishDate(reservation.checkIn())
+                + " | Check-out: " + TextFormat.englishDate(reservation.checkOut())
+                + " | " + nights + (nights == 1 ? " night" : " nights");
+    }
+
+    @Override
+    protected String chargesLine(Price price) {
+        return "Nights: " + TextFormat.englishMoney(price.subtotal());
+    }
+
+    @Override
+    protected String discountLine(Price price) {
+        return "Discount: " + TextFormat.englishMoney(price.discount());
+    }
+
+    @Override
+    protected String totalLine(Price price) {
+        return "Total: " + TextFormat.englishMoney(price.total());
+    }
+}
diff --git a/src/main/java/hotel/documents/DocumentLayout.java b/src/main/java/hotel/documents/DocumentLayout.java
new file mode 100644
index 0000000..69adb84
--- /dev/null
+++ b/src/main/java/hotel/documents/DocumentLayout.java
@@ -0,0 +1,52 @@
+package hotel.documents;
+
+import hotel.reservations.Price;
+import hotel.reservations.Reservation;
+import hotel.rooms.Room;
+
+/**
+ * The document the guest gets. Every document follows the same sequence of lines; each layout writes its own
+ * lines (language, identification, extras at the end).
+ */
+public abstract class DocumentLayout {
+
+    public abstract String title();
+
+    protected abstract String header(Reservation reservation);
+
+    protected abstract String guestLines(Reservation reservation);
+
+    protected abstract String roomLine(Room room);
+
+    protected abstract String stayLine(Reservation reservation);
+
+    protected abstract String chargesLine(Price price);
+
+    protected abstract String discountLine(Price price);
+
+    protected abstract String totalLine(Price price);
+
+    /** Lines after the total; none by default. */
+    protected String closingLines(Price price) {
+        return null;
+    }
+
+    public final String render(Reservation reservation, Room room) {
+        Price price = reservation.price();
+        StringBuilder text = new StringBuilder();
+        text.append(header(reservation)).append('\n');
+        text.append(guestLines(reservation)).append('\n');
+        text.append(roomLine(room)).append('\n');
+        text.append(stayLine(reservation)).append('\n');
+        text.append(chargesLine(price)).append('\n');
+        if (price.discount().signum() > 0) {
+            text.append(discountLine(price)).append('\n');
+        }
+        text.append(totalLine(price)).append('\n');
+        String closing = closingLines(price);
+        if (closing != null) {
+            text.append(closing).append('\n');
+        }
+        return text.toString();
+    }
+}
